type planeVectors struct {
	Master      string `json:"master"`
	Ciphertexts struct {
		TOTP struct{ Plaintext, Stored string } `json:"totp"`
		SMTP struct{ Plaintext, Stored string } `json:"smtp"`
	} `json:"ciphertexts"`
	TOTP struct {
		Secret  string            `json:"secret"`
		EpochMs int64             `json:"epochMs"`
		Codes   map[string]string `json:"codes"`
		Checks  []struct {
			Code  string `json:"code"`
			Valid bool   `json:"valid"`
		} `json:"checks"`
		KeyURIs []struct{ Label, URI string } `json:"keyuris"`
	} `json:"totp"`
	TokenHash struct{ Token, Hash string } `json:"tokenHash"`
}

func loadPlane(t *testing.T) planeVectors {
	t.Helper()
	b, err := os.ReadFile("testdata/auth_plane_vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v planeVectors
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

func TestSecretCipherDecryptsNodeCiphertexts(t *testing.T) {
	v := loadPlane(t)
	if got, ok := DecryptSecret(v.Ciphertexts.TOTP.Stored, v.Master); !ok || got != v.Ciphertexts.TOTP.Plaintext {
		t.Fatalf("totp: %q %v", got, ok)
	}
	if got, ok := DecryptUserSmtpSecret(v.Ciphertexts.SMTP.Stored, v.Master); !ok || got != v.Ciphertexts.SMTP.Plaintext {
		t.Fatalf("smtp: %q %v", got, ok)
	}
	// Domain separation: neither decrypts under the other kind's key.
	if _, ok := DecryptUserSmtpSecret(v.Ciphertexts.TOTP.Stored, v.Master); ok {
		t.Fatal("TOTP ciphertext decrypted as SMTP")
	}
	if _, ok := DecryptSecret(v.Ciphertexts.SMTP.Stored, v.Master); ok {
		t.Fatal("SMTP ciphertext decrypted as TOTP")
	}
	if _, ok := DecryptSecret(v.Ciphertexts.TOTP.Stored, "other"); ok {
		t.Fatal("wrong master accepted")
	}
}

func TestSecretCipherRoundTripAndGarbage(t *testing.T) {
	enc, err := EncryptSecret("s3cret", "m")
	if err != nil {
		t.Fatal(err)
	}
	if !regexp.MustCompile(`^aesgcm\$[\w-]+\$[\w-]+\$[\w-]+$`).MatchString(enc) || regexp.MustCompile(`s3cret`).MatchString(enc) {
		t.Fatalf("stored form %q", enc)
	}
	if got, ok := DecryptSecret(enc, "m"); !ok || got != "s3cret" {
		t.Fatal("round trip failed")
	}
	tampered := enc[:len(enc)-2] + "AA"
	for _, s := range []string{"", "garbage", "aesgcm$a$b", "aesgcm$$$", tampered, "plain$x$y$z"} {
		if _, ok := DecryptSecret(s, "m"); ok {
			t.Fatalf("%q decrypted", s)
		}
	}
	if _, ok := DecryptSecret(enc, ""); ok {
		t.Fatal("empty master decrypted")
	}
	if _, err := EncryptSecret("x", ""); err == nil {
		t.Fatal("empty master must fail to encrypt")
	}
	smtp, _ := EncryptUserSmtpSecret("pw", "m")
	if got, ok := DecryptUserSmtpSecret(smtp, "m"); !ok || got != "pw" {
		t.Fatal("smtp round trip failed")
	}
}

func TestTOTPMatchesOtplib(t *testing.T) {
	v := loadPlane(t)
	t0 := time.UnixMilli(v.TOTP.EpochMs)
	for d, want := range v.TOTP.Codes {
		n, _ := strconv.Atoi(d)
		if got := TOTPCode(v.TOTP.Secret, t0.Add(time.Duration(n)*30*time.Second)); got != want {
			t.Errorf("code at %+d steps = %s, want %s", n, got, want)
		}
	}
	for _, c := range v.TOTP.Checks {
		if got := TOTPCheck(c.Code, v.TOTP.Secret, t0); got != c.Valid {
			t.Errorf("check(%s) = %v, want %v (window 1)", c.Code, got, c.Valid)
		}
	}
	for _, k := range v.TOTP.KeyURIs {
		if got := TOTPKeyURI(k.Label, "StreamHub", v.TOTP.Secret); got != k.URI {
			t.Errorf("keyuri(%q):\n got %s\nwant %s", k.Label, got, k.URI)
		}
	}
	if s := GenerateTOTPSecret(); !regexp.MustCompile(`^[A-Z2-7]{16}$`).MatchString(s) {
		t.Fatalf("secret %q", s)
	}
}

func TestTokenHashAndFormat(t *testing.T) {
	v := loadPlane(t)
	if got := HashToken(v.TokenHash.Token); got != v.TokenHash.Hash {
		t.Fatalf("hash = %s", got)
	}
	tok := GenerateAPIToken()
	if !regexp.MustCompile(`^sk_[A-Za-z0-9_-]{43}$`).MatchString(tok) || tok == GenerateAPIToken() {
		t.Fatalf("token %q", tok)
	}
}

func TestLegacyScope(t *testing.T) {
	for in, want := range map[Scope]Scope{ScopeUser: ScopeApp, ScopeApp: ScopeApp, ScopeGlobal: ScopeGlobal} {
		if got := (&Principal{Scope: in}).LegacyScope(); got != want {
			t.Errorf("%s → %s", in, got)
		}
	}
}
